// Classify barrier category and validate
const body = $input.first().json.body || $input.first().json;

if (!body.client_id) {
  throw new Error('client_id is required for barrier follow-up.');
}

const rawCategory = (body.barrier_category || 'other').toLowerCase();
const validCategories = [
  'transport',
  'schedule',
  'communication',
  'financial_or_logistical',
  'social_support',
  'clinic_access',
  'technology',
  'other'
];

const category = validCategories.includes(rawCategory) ? rawCategory : 'other';
const notes = body.notes || 'Client reported non-clinical obstacle to care attendance';

return [{
  json: {
    client_id: body.client_id,
    barrier_category: category,
    notes: notes,
    priority: category === 'transport' ? 'high' : 'normal',
    channel: body.channel || 'sms'
  }
}];

